[ExtensionOf(classStr(AVAItemSetLineCalculation))]
 internal final class AVAItemSetLineCalculation_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
/// <returns>AmountMST</returns>
public  static AmountMST custInvoicedItemSetComponentAmount(CustInvoiceTrans    _custInvoiceTrans)
{
    CustInvoiceTrans        locComponentCustInvoiceTrans;
    CustInvoiceTrans        locItemSetCustInvoiceTrans;
    LineAmount              componentAmount = next custInvoicedItemSetComponentAmount(_custInvoiceTrans);
    LineAmount              HK2AmountSum;
    InventTable             curInventTable = InventTable::find(_custInvoiceTrans.ItemId);
    CustInvoiceTrans        custInvoiceTrans;

    InventTransId       avaItemSetParent = _custInvoiceTrans.AVAItemSetParent;
    RecId               curRecId = _custInvoiceTrans.RecId;
    InvoiceId           curInvoiceId = _custInvoiceTrans.InvoiceId;
    InvoiceDate         curInvoiceDate = _custInvoiceTrans.InvoiceDate;

    AmountMST               curHK2Amount = _custInvoiceTrans.PriceUnit != 0 ?  (curInventTable.NDX_HK2() *  _custInvoiceTrans.Qty) / _custInvoiceTrans.PriceUnit : curInventTable.NDX_HK2() *  _custInvoiceTrans.Qty;

    HK2AmountSum += curHK2Amount;

    while select locComponentCustInvoiceTrans
        where locComponentCustInvoiceTrans.AVAItemSetParent   == avaItemSetParent
           && locComponentCustInvoiceTrans.RecId              != curRecId
           && locComponentCustInvoiceTrans.InvoiceId          == curInvoiceId
           && locComponentCustInvoiceTrans.InvoiceDate        == curInvoiceDate
    {
        curInventTable = InventTable::find(locComponentCustInvoiceTrans.ItemId);
        HK2AmountSum += locComponentCustInvoiceTrans.PriceUnit != 0 ? (curInventTable.NDX_HK2() *  locComponentCustInvoiceTrans.Qty) / locComponentCustInvoiceTrans.PriceUnit : curInventTable.NDX_HK2() *  locComponentCustInvoiceTrans.Qty;
    }

    select firstonly locItemSetCustInvoiceTrans
        where locItemSetCustInvoiceTrans.InventTransId == avaItemSetParent
           && locItemSetCustInvoiceTrans.InvoiceId     == curInvoiceId
           && locItemSetCustInvoiceTrans.InvoiceDate   == curInvoiceDate;

    if (HK2AmountSum != 0)
    {
        componentAmount = locItemSetCustInvoiceTrans.AVAItemSetLineAmount != 0 ? (curHK2Amount / HK2AmountSum) * locItemSetCustInvoiceTrans.AVAItemSetLineAmount : (curHK2Amount / HK2AmountSum) * locItemSetCustInvoiceTrans.LineAmount;
    }
    return componentAmount;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_vendInvoiceTrans">_vendInvoiceTrans</param>
/// <returns>AmountMST</returns>
public  static AmountMST custInvoicedItemSetComponentAmountVend(VendInvoiceTrans    _vendInvoiceTrans)
{
    VendInvoiceTrans        locComponentVendInvoiceTrans;
    VendInvoiceTrans        locItemSetVendInvoiceTrans;
    LineAmount              componentAmount = next custInvoicedItemSetComponentAmountVend(_vendInvoiceTrans);
    LineAmount              HK2AmountSum;
    InventTable             curInventTable = InventTable::find(_vendInvoiceTrans.ItemId);
    VendInvoiceTrans        custInvoiceTrans;

    InventTransId       avaItemSetParent = _vendInvoiceTrans.AVAItemSetParent;
    RecId               curRecId = _vendInvoiceTrans.RecId;
    InvoiceId           curInvoiceId = _vendInvoiceTrans.InvoiceId;
    InvoiceDate         curInvoiceDate = _vendInvoiceTrans.InvoiceDate;

    AmountMST               curHK2Amount = _vendInvoiceTrans.PriceUnit != 0 ?  (curInventTable.NDX_HK2() *  _vendInvoiceTrans.Qty) / _vendInvoiceTrans.PriceUnit : curInventTable.NDX_HK2() *  _vendInvoiceTrans.Qty;

    HK2AmountSum += curHK2Amount;

    while select locComponentVendInvoiceTrans
        where locComponentVendInvoiceTrans.AVAItemSetParent   == avaItemSetParent
           && locComponentVendInvoiceTrans.RecId              != curRecId
           && locComponentVendInvoiceTrans.InvoiceId          == curInvoiceId
           && locComponentVendInvoiceTrans.InvoiceDate        == curInvoiceDate
    {
        curInventTable = InventTable::find(locComponentVendInvoiceTrans.ItemId);
        HK2AmountSum += locComponentVendInvoiceTrans.PriceUnit != 0 ? (curInventTable.NDX_HK2() *  locComponentVendInvoiceTrans.Qty) / locComponentVendInvoiceTrans.PriceUnit : curInventTable.NDX_HK2() *  locComponentVendInvoiceTrans.Qty;
    }

    select firstonly locItemSetVendInvoiceTrans
        where locItemSetVendInvoiceTrans.InventTransId == avaItemSetParent
           && locItemSetVendInvoiceTrans.InvoiceId     == curInvoiceId
           && locItemSetVendInvoiceTrans.InvoiceDate   == curInvoiceDate;

    if (HK2AmountSum != 0)
    {
        componentAmount = locItemSetVendInvoiceTrans.AVAItemSetLineAmount != 0 ? (curHK2Amount / HK2AmountSum) * locItemSetVendInvoiceTrans.AVAItemSetLineAmount : (curHK2Amount / HK2AmountSum) * locItemSetVendInvoiceTrans.LineAmount;
    }
    return componentAmount;
}
